// BotForge signs every call: hex HMAC-SHA256 over "<timestamp>." + the raw body, using
// N8N_WEBHOOK_SIGNING_SECRET (apps/api/app/integrations/n8n_client.py sign()/verify_callback()).
// Fails CLOSED: no secret configured, missing headers, stale timestamp or bad MAC => rejected.
const crypto = require('crypto');
const item = $input.first();
const reject = (reason) => [{ json: { verified: false, reason } }];
const secret = $env['N8N_WEBHOOK_SIGNING_SECRET'] || '';
if (!secret) return reject('signing secret is not configured on this n8n');
const h = item.json.headers || {};
const sig = String(h['x-botforge-signature'] || '');
const ts = String(h['x-botforge-timestamp'] || '');
if (!sig || !ts) return reject('missing signature headers');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('stale or malformed timestamp');
if (!item.binary || !item.binary.data) return reject('raw body unavailable (Webhook option rawBody must be on)');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(sig, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');
return [{ json: { ...item.json, verified: true } }];

// DEMO FIXTURE - every name, id, price, doctor, slot and order in this workflow is fictional demo data.
// State (bookings, counters) lives in n8n workflow static data and is NOT part of this export.
const body = $input.first().json.body || {};
const a = body.args || {};
const S = $getWorkflowStaticData('global');
S.bookings = S.bookings || {};
S.counter = S.counter || 0;
const need = (fields) => fields.filter((f) => a[f] === undefined || a[f] === null || String(a[f]).trim() === '');
const bad = (error, extra = {}) => [{ json: { ok: false, error, ...extra } }];
const nextId = (prefix) => { S.counter += 1; return prefix + '-' + String(1000 + S.counter); };
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const isTime = (s) => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));

const MENU = { haircut: { price: 600, minutes: 45 }, hair_coloring: { price: 2800, minutes: 120 }, facial: { price: 1500, minutes: 60 }, manicure: { price: 700, minutes: 45 }, spa_massage: { price: 2200, minutes: 60 } };
const ADDONS = { deep_conditioning: 400, head_massage: 300, gel_polish: 350 };
const HOURS = ['10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00'];
const taken = (date, time) => Object.values(S.bookings).some((b) => b.status === 'confirmed' && b.date === date && b.time === time);
switch (a.action) {
  case 'get_quote': {
    const m = need(['service']); if (m.length) return bad('missing fields: service');
    const svc = MENU[a.service]; if (!svc) return bad('unknown service', { services: Object.keys(MENU) });
    const adds = Array.isArray(a.add_ons) ? a.add_ons : [];
    const unknown = adds.filter((x) => !(x in ADDONS)); if (unknown.length) return bad('unknown add-ons: ' + unknown.join(', '), { add_ons: Object.keys(ADDONS) });
    const total = svc.price + adds.reduce((n, x) => n + ADDONS[x], 0);
    return [{ json: { ok: true, service: a.service, base_price_inr: svc.price, add_ons: adds, total_inr: total, duration_minutes: svc.minutes + adds.length * 10 } }];
  }
  case 'book_appointment': {
    const m = need(['name', 'phone', 'service', 'date', 'time']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!MENU[a.service]) return bad('unknown service', { services: Object.keys(MENU) });
    if (!isDate(a.date) || !isTime(a.time)) return bad('date must be YYYY-MM-DD and time HH:MM (24h)');
    if (!HOURS.includes(a.time)) return bad('salon bookings run 10:00-18:00 on the hour', { open_slots: HOURS.filter((t) => !taken(a.date, t)) });
    if (taken(a.date, a.time)) return bad('slot already taken', { open_slots: HOURS.filter((t) => !taken(a.date, t)) });
    const adds = Array.isArray(a.add_ons) ? a.add_ons : [];
    const unknownAdds = adds.filter((x) => !(x in ADDONS)); if (unknownAdds.length) return bad('unknown add-ons: ' + unknownAdds.join(', '), { add_ons: Object.keys(ADDONS) });
    const price = MENU[a.service].price + adds.reduce((n, x) => n + ADDONS[x], 0);
    const id = nextId('LGS');
    S.bookings[id] = { id, name: a.name, phone: a.phone, service: a.service, add_ons: adds, stylist: a.stylist || 'any available', date: a.date, time: a.time, price_inr: price, status: 'confirmed' };
    return [{ json: { ok: true, booking_id: id, service: a.service, add_ons: adds, date: a.date, time: a.time, stylist: a.stylist || 'any available', price_inr: price, status: 'confirmed' } }];
  }
  case 'get_booking': {
    const b = S.bookings[a.booking_id]; if (!b) return bad('no booking found for that id');
    return [{ json: { ok: true, ...b } }];
  }
  default: return bad('unknown action', { valid_actions: ['get_quote', 'book_appointment', 'get_booking'] });
}
